const N:usize=9;const Q:usize=24;const R:usize=4;const INPUT:usize=55;
fn put(out:&mut[u8],at:usize,x:i64){out[at..at+8].copy_from_slice(&x.to_le_bytes());}
fn owned(g:&[[bool;N];N],level:&[i64;N],n:usize,u:usize,out:&mut[usize;N])->usize{let mut z=0;for v in 0..n{if g[u][v]&&level[u]==0&&level[v]==0{out[z]=v;z+=1;}}z}
fn repair(g:&[[bool;N];N],level:&[i64;N],mate:&mut[i64;N],n:usize,u:i64){if u<0{return;}let z=u as usize;if level[z]!=0||mate[z]>=0{return;}for v in 0..n{if g[z][v]&&level[v]==0&&mate[v]<0{mate[z]=v as i64;mate[v]=z as i64;return;}}}
fn promote(g:&[[bool;N];N],level:&mut[i64;N],mate:&mut[i64;N],n:usize,u:usize,tape:&[usize;R],r:usize,used:&mut usize)->bool{let mut list=[0usize;N];let count=owned(g,level,n,u,&mut list);if count==0||*used>=r||tape[*used]>=count{return false;}let y=list[tape[*used]];*used+=1;let w=mate[u];let x=mate[y];if w>=0{mate[w as usize]=-1;mate[u]=-1;}if x>=0{mate[x as usize]=-1;mate[y]=-1;}level[u]=1;level[y]=1;mate[u]=y as i64;mate[y]=u as i64;repair(g,level,mate,n,w);if x!=w{repair(g,level,mate,n,x);}true}
#[no_mangle]
pub unsafe extern "C" fn two_level_dynamic_maximal_matching_insertions(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<3||length>INPUT{return -1;}let a=std::slice::from_raw_parts(input,length);let(n0,q0)=(a[0],a[1]);if(n0!=4&&n0!=9)||q0<0||q0>Q as i64||q0>n0*(n0-1)/2{return -1;}let n=n0 as usize;let q=q0 as usize;let mut u=[0usize;Q];let mut v=[0usize;Q];let mut seen=[[false;N];N];let mut p=2;for e in 0..q{let x=a[p];let y=a[p+1];p+=2;if x<0||y<=x||y>=n0||seen[x as usize][y as usize]{return -1;}seen[x as usize][y as usize]=true;u[e]=x as usize;v[e]=y as usize;}if p>=length{return -1;}let r0=a[p];p+=1;if r0<0||r0>R as i64||length!=p+r0 as usize{return -1;}let r=r0 as usize;let mut tape=[0usize;R];for i in 0..r{let x=a[p+i];if x<0||x>=n0{return -1;}tape[i]=x as usize;}let mut g=[[false;N];N];let mut level=[0i64;N];let mut mate=[-1i64;N];let mut used=0;let threshold=if n==4{2}else{3};for e in 0..q{let x=u[e];let y=v[e];g[x][y]=true;g[y][x]=true;if level[x]==1||level[y]==1{continue;}if mate[x]<0&&mate[y]<0{mate[x]=y as i64;mate[y]=x as i64;}let mut tmp=[0usize;N];let dx=owned(&g,&level,n,x,&mut tmp);let dy=owned(&g,&level,n,y,&mut tmp);let who=if dx>dy||(dx==dy&&x<y){x}else{y};let count=owned(&g,&level,n,who,&mut tmp);if count>=threshold&&!promote(&g,&mut level,&mut mate,n,who,&tape,r,&mut used){return -1;}}if used!=r{return -1;}let bytes=8*(1+2*n);if output.is_null()||capacity<bytes{return -2;}let out=std::slice::from_raw_parts_mut(output,bytes);put(out,0,n as i64);for i in 0..n{put(out,8+8*i,level[i]);}for i in 0..n{put(out,8+8*n+8*i,mate[i]);}bytes as i64}
